+  const match = /^(\d+(?:\.\d+)?)\s*([a-z]*)$/i.exec(text.trim());
+  if (!match) throw new RangeError(`invalid size: ${JSON.stringify(text)}`);
+  const unit = match[2] === "" ? "b" : match[2].toLowerCase();
+  const multiplier = Object.hasOwn(UNIT_BYTES, unit) ? UNIT_BYTES[unit] : undefined;
